{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "All clinical trial registrations either being planned, or currently underway to diagnose, treat or prevent COVID-19 were eligible for inclusion... This included patients known to be infected with COVID-19 as well as healthy volunteers, healthcare workers or other patient populations where health related outcomes were assessed in the context of COVID-19... no limitations on study design were applied so that all research and observational studies would be incorporated, including retrospective studies.",
      "reason": "Eligibility criteria specify populations (COVID-19 patients, healthy volunteers, healthcare workers, other populations in the COVID-19 context), focus (diagnose, treat or prevent COVID-19), and explicitly state that no study design restrictions were applied."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "The review was not limited by outcome, language or intervention given the desire to capture all clinical trial registrations planning to or currently evaluating any COVID-19 diagnostic, prevention or treatment modality.",
      "reason": "Language is explicitly stated as unrestricted, and publication status is implicitly all trial registrations regardless of status. However, no dissemination year/publication date criteria are reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "All clinical trial registrations either being planned, or currently underway to diagnose, treat or prevent COVID-19 were eligible for inclusion",
      "reason": "The review includes trial registrations (planned and ongoing studies), not completed studies with outcome results; the distinction between outcomes not measured versus results not reported does not apply to this review of registrations."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Interventional studies were categorised as 'randomised control trials (RCT)'; 'quasi-randomised trials'; or 'non-randomised interventional studies'. For observational and epidemiological research one of the following study designs were selected: 'cohort-study'; 'case report'; 'case series'; 'case-control'; 'cross-sectional'; or 'prognostic'.",
      "reason": "Groups used in the descriptive synthesis (study design categories and intervention types such as treatment, diagnostic, preventative) are specified, but this is a descriptive mapping of registrations with no formal comparisons defined in review objectives, so the grouping is not explicitly linked to comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The review was not limited by outcome, language or intervention... Eligibility was not restricted to clinical trials only; no limitations on study design were applied",
      "reason": "The review explicitly imposed no notable restrictions on eligibility (no outcome, language, intervention, or study design limits), so there are no notable restrictions requiring rationale."
    }
  ],
  "confidence": 85
}

